    let scroll = self.output_table.scroll();
    let following = scroll.offset().y <= -scroll.max_offset().y + px(1.);
    self.tasks[ix].apply(event);
    if unseen {
        return;
    }
    if (following || self.output_locked) && latest {
        self.output_table.scroll_to_end();
    }
    cx.notify();
