/// for prose, as [`prose`] reads it.
fn text_of(value: &Value) -> String {
    match value {
        Value::Array(lines) if !lines.is_empty() && lines.iter().all(Value::is_array) => lines
            .iter()
            .map(|line| {
                line.as_array()
                    .into_iter()
                    .flatten()
                    .map(|piece| match piece {
                        Value::String(text) => text.clone(),
                        other => prose(other),
                    })
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
            .join("\n"),
        other => prose(other),
    }
}

