        match self {
            Self::Read => Some("Choosing what to read…"),
            Self::Edit => Some("Writing the edit…"),
            Self::Command => Some("Writing the command…"),
            Self::Web => Some("Preparing the request…"),
            Self::Agent => Some("Briefing the agent…"),
