tool_use_result.content:
//! The sidebar at the right of the task view while a task runs, listing the
//! spec files it references: those its prompt imports from, then those the
//! harness reads, edits, or writes, in the spec location or under
//! `.claude/reference`, each once.

use std::path::{Path, PathBuf};

use gpui_kit::assets::IconName;
use gpui_kit::component::tooltip::Tooltip;
use gpui_kit::component::{ActiveTheme as _, Icon, Sizable as _, h_flex, v_flex};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;

use crate::file_link::OpenFile;
use crate::hidden_anchor;
use crate::task_table::ReplyPart;

/// How wide the sidebar starts, and how narrow it can be dragged.
pub const WIDTH: Pixels = px(260.);
pub const MIN_WIDTH: Pixels = px(160.);

/// Where the reference files built from the spec are, in the project.
const REFERENCE_DIR: &str = ".claude/reference";

/// A spec file the task references.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Referenced {
    pub path: PathBuf,
    /// Whether the harness edited or wrote it, rather than only reading or
    /// importing it.
    pub edited: bool,
}

/// The spec files a task references: `imported`, the files its prompt imports
/// from, then those its reply's tool calls work on, each once, in the order
/// first referenced.
pub fn collect(imported: &[PathBuf], parts: &[ReplyPart], project_dir: &Path) -> Vec<Referenced> {
    let spec_dir = hidden_anchor::spec_dir(project_dir);
    let reference_dir = project_dir.join(REFERENCE_DIR);
    let mut files: Vec<Referenced> = imported
        .iter()
        .map(|path| Referenced {
            path: path.clone(),
            edited: false,
        })
        .collect();
    for part in parts {
        let ReplyPart::Tool(call) = part else {
            continue;
        };
        let Some(summary) = call.summary.as_deref().filter(|_| call.works_on_a_file()) else {
            continue;
        };
        let path = project_dir.join(summary);
        let is_spec = spec_dir.as_ref().is_some_and(|dir| path.starts_with(dir))
            || path.starts_with(&reference_dir);
        if !is_spec {
            continue;
        }
        let edited = !matches!(call.name.as_str(), "Read" | "NotebookRead");
        match files.iter_mut().find(|file| file.path == path) {
            Some(file) => file.edited |= edited,
            None => files.push(Referenced { path, edited }),
        }
    }
    files
}

/// The sidebar's contents: a header with how many files are listed, then a
/// row per file, which opens it.
pub fn render(
    files: &[Referenced],
    project_dir: Option<&Path>,
    scroll: &ScrollHandle,
    open: OpenFile,
    cx: &App,
) -> AnyElement {
    let theme = cx.theme();
    let header = h_flex()
        .flex_none()
        .justify_between()
        .gap_2()
        .px_3()
        .py_2()
        .text_sm()
        .font_semibold()
        .child("Referenced spec")
        .child(
            div()
                .text_xs()
                .font_normal()
                .text_color(theme.muted_foreground)
                .child(files.len().to_string()),
        );
    let rows = files.iter().enumerate().map(|(ix, file)| {
        let shown = project_dir
            .and_then(|dir| file.path.strip_prefix(dir).ok())
            .unwrap_or(&file.path)
            .display()
            .to_string();
        let full: SharedString = file.path.display().to_string().into();
        let (path, open) = (file.path.clone(), open.clone());
        // Lets UI tests find each row; inert in normal builds.
        gpui_kit::TestSupportExt::test_support(h_flex().id(("referenced-file", ix)))
            .gap_2()
            .px_3()
            .py_1()
            .text_sm()
            .cursor_pointer()
            .hover(|row| row.bg(theme.list_hover))
            .child(
                Icon::new(IconName::File)
                    .xsmall()
                    .text_color(theme.muted_foreground),
            )
            .child(div().flex_1().min_w_0().truncate().child(shown))
            .when(file.edited, |row| {
                row.child(
                    Icon::new(IconName::Pencil)
                        .xsmall()
                        .text_color(theme.muted_foreground),
                )
            })
            .tooltip(move |window, cx| Tooltip::new(full.clone()).build(window, cx))
            .on_click(move |_, window, cx| open(path.clone(), window, cx))
    });
    let list = div()
        .id("referenced-files-list")
        .size_full()
        .overflow_y_scroll()
        .track_scroll(scroll)
        .when(files.is_empty(), |list| {
            list.child(
                div()
                    .px_3()
                    .py_1()
                    .text_sm()
                    .text_color(theme.muted_foreground)
                    .child("No spec files referenced yet"),
            )
        })
        .children(rows);
    // Lets UI tests find the sidebar; inert in normal builds.
    gpui_kit::TestSupportExt::test_support(v_flex().id("referenced-files"))
        .size_full()
        .bg(theme.background)
        .border_l_1()
        .border_color(theme.border)
        .child(header)
        .child(div().flex_1().min_h_0().child(crate::scrollbar::with_scrollbar(
            "referenced-files",
            scroll,
            list,
            true,
            None,
            cx,
        )))
        .into_any_element()
}

#[cfg(test)]
mod tests {
    use std::fs;
    use std::path::Path;

    use super::{Referenced, collect};
    use crate::harness::HarnessEvent;
    use crate::task_table::Reply;

    /// Imports come first, then the spec files the harness works on, each
    /// once, with an edit marking a file edited; files elsewhere are left out.
    #[test]
    fn lists_imports_then_spec_files_worked_on_once() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/referenced-spec-test");
        fs::remove_dir_all(&dir).ok();
        fs::create_dir_all(&dir).unwrap();
        fs::write(dir.join("piton.config.pi"), "root: ./spec\n").unwrap();
        let mut reply = Reply::default();
        let mut id = 0;
        let mut tool = |reply: &mut Reply, name: &str, path: String| {
            id += 1;
            reply.apply(HarnessEvent::ToolStarted {
                id: id.to_string(),
                name: name.into(),
            });
            reply.apply(HarnessEvent::ToolInput {
                id: id.to_string(),
                summary: path,
            });
        };
        let long = format!("spec/{}/index.pi", "deep".repeat(40));
        tool(&mut reply, "Read", dir.join("spec/a.pi").display().to_string());
        tool(&mut reply, "Read", dir.join("src/main.rs").display().to_string());
        tool(&mut reply, "Read", dir.join(".claude/reference/A.md").display().to_string());
        tool(&mut reply, "Edit", dir.join("spec/a.pi").display().to_string());
        tool(&mut reply, "Read", dir.join("spec/b/index.pi").display().to_string());
        tool(&mut reply, "Write", dir.join(&long).display().to_string());
        let imported = [dir.join("spec/b/index.pi")];
        let files = collect(&imported, &reply.parts, &dir);
        let expected = [
            ("spec/b/index.pi", false),
            ("spec/a.pi", true),
            (".claude/reference/A.md", false),
            (long.as_str(), true),
        ]
        .map(|(path, edited)| Referenced {
            path: dir.join(path),
            edited,
        });
        assert_eq!(files, expected);
    }
}

